//! providers 解析冒烟测试：验证能同时解析 `apiKeys:` 与 `task.keyPool:` 两种结构。
use ne_engine::providers;

const OLD_STYLE: &str = r#"
providers:
  workbuddy:
    baseUrl: https://api.example.com/v1
    apiKeys:
      - sk-old-1
      - sk-old-2
"#;

const NEW_STYLE: &str = r#"
# Generated by Mini-PRoot
providers:
  workbuddy:
    baseUrl: https://api.example.com/v1
    apiKey: [REDACTED]
    api: openai-completions
    task:
      keyPool:
        - sk-new-1
        - sk-new-2
        - sk-new-3
    models:
      - name: glm-5.3-flash
        contextWindow: 512000
  gcmod:
    baseUrl: https://api.gcmod.example/v1
    task:
      keyPool:
        - sk-gc-1
"#;

#[test]
fn parses_old_style() {
    let p = providers::parse_models_yml(OLD_STYLE);
    let a = p.map.get("workbuddy").expect("workbuddy 缺失");
    assert_eq!(a.base_url, "https://api.example.com/v1");
    assert_eq!(a.keys.len(), 2, "旧结构应取到 2 把 key，实际 {:?}", a.keys.len());
    assert_eq!(a.key_source, "apiKeys");
}

#[test]
fn parses_new_style() {
    let p = providers::parse_models_yml(NEW_STYLE);
    let a = p.map.get("workbuddy").expect("workbuddy 缺失");
    assert_eq!(a.base_url, "https://api.example.com/v1");
    // 新结构：1 把单 key + 3 把 keyPool
    assert_eq!(a.keys.len(), 4, "新结构应取到 4 把 key，实际 {:?} 来源={}", a.keys.len(), a.key_source);
    let g = p.map.get("gcmod").expect("gcmod 缺失");
    assert_eq!(g.keys.len(), 1);
}

#[test]
#[ignore]
fn parses_real_models_yml() {
    // 对真实 /root/.omp/agent/models.yml 解析（只报数量，不打印 key）
    let dir = providers::agent_dir();
    let (provs, roles) = providers::load_from_dir(&dir).expect("读真实 models.yml 失败");
    println!("agent 目录 = {}", dir.display());
    for (name, p) in &provs.map {
        let tails: Vec<String> = p.keys.iter().map(|k| k.chars().rev().take(4).collect::<Vec<_>>().into_iter().rev().collect()).collect();
        println!("  {name}: base_url={} keys={} 来源={} 末4位={:?}",
                 if p.base_url.is_empty() { "(空)" } else { &p.base_url }, p.keys.len(), p.key_source, tails);
    }
    println!("modelRoles: {roles:?}");
    let total: usize = provs.map.values().map(|p| p.keys.len()).sum();
    assert!(total > 0, "应至少解析出 1 把 key（Python 版在此文件上取到 0）");
    // 关键断言：不能把 models 列表里的模型名误当 key
    for p in provs.map.values() {
        for k in &p.keys {
            assert!(
                !k.contains("flash") && !k.contains("pro-alpha") && !k.ends_with("glm-5.3"),
                "误收模型名当 key：{k}"
            );
            assert!(!k.is_empty(), "空 key");
        }
    }
    println!("总 key 数（含 apiKey 与 keyPool）={total}");
}
